<script setup>
import {ref,onMounted,onUnmounted,computed} from 'vue';
import {createClient} from '@supabase/supabase-js';
import {mountIsland} from './island.js';
const canvas=ref(null),phase=ref(.25),daylight=ref(1),weather=ref('Sunny'),temperature=ref(20),thermal=ref('Comfortable'),swimming=ref(false),wetness=ref(0),weatherSource=ref('Simulated fallback'),wind=ref(0),previewNeeds=ref({health:100,hunger:100,thirst:100,morale:100,energy:100}),journal=ref([]),decision=ref(null),world=ref(null),connected=ref(false),loading=ref(true),tab=ref('journal'),chatMessages=ref([]),chatText=ref(''),chatName=ref(''),chatEmail=ref(''),chatSending=ref(false),chatError=ref(''),chatNotice=ref(''),chatUser=ref(null),chatIsAdmin=ref(false),adminDaylight=ref(false),authOpen=ref(false),authMode=ref('signin'),authEmail=ref(''),authPassword=ref(''),authBusy=ref(false),authError=ref(''),authNotice=ref(''),memoryPlaces=ref([]),memoryFilter=ref('all'),activity=ref({swimming:false,resting:false,freshwaterNearby:false,georgeMoving:false,sitting:false});
let dispose,refresh;let lastSurvivalUpdate=Date.now();
const supabaseUrl=import.meta.env.VITE_SUPABASE_URL;
const supabaseKey=import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY;
const client=supabaseUrl&&supabaseKey?createClient(supabaseUrl,supabaseKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}}):null;
const journalPreview=[{id:'journal-preview-first',island_day:1,perceived_time:'morning',title:'My first journal entry',entry:'I have begun keeping a journal of my life on this island. There is a camp I can return to, and I need to pay attention to my hunger, thirst and energy. My current priority is explore. I want to learn what this place holds, but I must remember to look after myself.'}];
const displayedJournal=computed(()=>connected.value?journal.value:journalPreview);
const timeLabel=computed(()=>{const h=phase.value*24;return h<5.5?'Night':h<7?'Dawn':h<11?'Morning':h<14?'Midday':h<18?'Afternoon':h<20.5?'Dusk':'Night'});
const clockLabel=computed(()=>{const total=Math.floor(phase.value*1440);return String(Math.floor(total/60)).padStart(2,'0')+':'+String(total%60).padStart(2,'0')});
const thought=computed(()=>{const n=connected.value&&world.value?.needs?world.value.needs:previewNeeds.value,a=activity.value;if(connected.value&&world.value?.inventory?.activity==='sitting')return 'I have been walking for half an hour. I am sitting down for five minutes before continuing my journey.';if(connected.value&&decision.value?.thought)return decision.value.thought;if(a.sitting)return 'I have been walking for half an hour. I need to sit down for five minutes, rest my legs, and then I can carry on exploring.';if(a.resting)return 'I have made it back to camp. I need to rest and recover my energy before I set out again.';if((n.energy??100)<30)return 'I am getting tired. I should head back towards my camp and regain my strength.';if((n.thirst??100)<65)return a.freshwaterNearby?'The stream is here. This is fresh water, so I can drink.':'My mouth is getting dry. I need to find the mountain stream; seawater is no good for drinking.';if((n.hunger??100)<35)return 'I am becoming hungry. I need to look for something safe to eat.';if(a.swimming)return 'I am in the water now. I should keep the shore close and avoid exhaustion.';if(thermal.value==='Cold'&&wetness.value>40)return 'I am cold and wet. I should find shelter and warm up.';if(thermal.value==='Hot')return 'The heat is draining me. I should take things slowly and conserve water.';if(a.georgeMoving)return 'I am exploring the island, watching for rocks and trees. I want to learn the landscape and remember the way back to camp.';return 'I am taking in my surroundings and deciding where to explore next. I should keep my camp and freshwater supply in mind.'});
const mood=computed(()=>{const e=world.value?.emotions;if(!e)return 'Unknown';const values=[['Joy',e.joy],['Curiosity',e.curiosity],['Fear',e.fear],['Frustration',e.frustration]];return values.sort((a,b)=>(b[1]??0)-(a[1]??0))[0][0]});
const emotions=computed(()=>{const e=world.value?.emotions||{};return [['Joy',e.joy],['Curiosity',e.curiosity],['Fear',e.fear],['Frustration',e.frustration]].map(([name,value])=>[name,Math.max(0,Math.min(100,Number(value??0)))])});
const project=computed(()=>world.value?.project||null);
const inventorySummary=computed(()=>world.value?.items||[]); const carriedItems=computed(()=>inventorySummary.value.filter(i=>i.owner==='george'&&i.state==='inventory')); const storedItems=computed(()=>inventorySummary.value.filter(i=>i.owner==='camp')); const itemLabel=(type)=>String(type||'Unknown item').replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase()); const journalTimestamp=(timestamp)=>{if(!timestamp)return null;const d=new Date(timestamp);return Number.isNaN(d.getTime())?null:new Intl.DateTimeFormat('en-NZ',{dateStyle:'medium',timeStyle:'short',timeZone:'Pacific/Auckland'}).format(d)+' NZ time';};
const needs=computed(()=>{const n=connected.value&&world.value?.needs?world.value.needs:previewNeeds.value;return [['Health',n.health??100],['Hunger',n.hunger??100],['Thirst',n.thirst??100],['Morale',n.morale??100],['Energy',n.energy??100]]});
// Survival percentages represent reserves, not an immediate death timer.
// 100 -> 0 thirst in ~48 hours without water at rest; heat/activity accelerate loss.
const SURVIVAL_KEY='george-survival-preview-v2';
let lastDrink=0;
try{const saved=JSON.parse(localStorage.getItem(SURVIVAL_KEY)||'null');if(saved?.needs&&Number.isFinite(saved.at)){previewNeeds.value=saved.needs;lastSurvivalUpdate=Math.max(saved.at,Date.now()-48*3600000)}}catch{}
function advanceSurvival({thermal,swimming,wetness,freshwaterNearby,georgeMoving,resting}){
 const now=Date.now(),minutes=Math.max(0,Math.min((now-lastSurvivalUpdate)/60000,48*60));lastSurvivalUpdate=now;
 const n=previewNeeds.value,hot=thermal==='Hot',cold=thermal==='Cold';
 const thirst=Math.max(0,n.thirst-minutes*(100/(48*60))*(1+(hot?.45:0)+(swimming?.3:0)+(georgeMoving?.15:0)));
 const hunger=Math.max(0,n.hunger-minutes*(100/(14*24*60))*(1+(swimming?.35:0)+(georgeMoving?.15:0)));
 const exposure=cold&&wetness>40?.015:0;
 const damage=minutes*((thirst<15?.045:0)+(hunger<10?.012:0)+exposure);
 const morale=Math.max(0,n.morale-minutes*(.004+(thirst<25?.01:0)));
 const energy=Math.max(0,Math.min(100,(n.energy??100)+minutes*(resting?1.25:-(georgeMoving?.085:.025))));
 const canDrink=freshwaterNearby&&!swimming&&now-lastDrink>120000&&thirst<85;
 const replenished=canDrink?100:thirst;
 if(canDrink)lastDrink=now;
 previewNeeds.value={health:Math.max(0,n.health-damage),hunger,thirst:replenished,morale,energy};
 // Seek only fresh river water. Sea swimming never replenishes thirst.
 window.__georgeNeedsRest=energy<25||(resting&&energy<92);
 window.__georgeNeedsWater=replenished<65&&!window.__georgeNeedsRest;
 try{localStorage.setItem(SURVIVAL_KEY,JSON.stringify({at:now,needs:previewNeeds.value}))}catch{}
}
async function loadData(){if(!client){loading.value=false;return}try{const [w,j,d,items,projectData]=await Promise.all([client.from('world_state').select('day,status,needs,inventory,emotions,stimulation,boredom,novelty_drive,clock_discovered').eq('id',1).maybeSingle(),client.from('george_journal').select('id,island_day,perceived_time,title,entry,created_at').order('island_day',{ascending:false}).order('island_minute',{ascending:false}).limit(20),client.from('george_decisions').select('goal,thought,created_at').order('created_at',{ascending:false}).limit(1).maybeSingle(),client.from('island_items').select('id,type_id,state,owner,durability').in('owner',['george','camp']),client.from('george_public_projects').select('*').eq('id',1).maybeSingle()]);if(w.error||j.error)throw w.error||j.error;world.value={...w.data,items:items.error?[]:items.data,project:projectData.error?null:projectData.data};journal.value=j.data||[];decision.value=d.error?null:d.data;connected.value=true}catch(e){connected.value=false;console.warn('Read-only Supabase data unavailable',e)}finally{loading.value=false}}
const visibleMemories=computed(()=>memoryPlaces.value.filter(m=>memoryFilter.value==='all'||m.subject_type===memoryFilter.value));
const memoryPosition=(v)=>Math.max(0,Math.min(100,(Number(v)+650)/1300*100))+'%';
async function refreshMemoryMap(){if(!client)return;const {data,error}=await client.from('george_spatial_memory_map').select('subject_type,subject_key,x,z,visits,confidence,is_available,last_seen_at').order('last_seen_at',{ascending:false}).limit(400);if(!error)memoryPlaces.value=data||[]}
async function refreshDivineChat(){if(!client)return;const {data,error}=await client.from('george_divine_messages').select('id,author_name,message,created_at,status,george_response').order('created_at',{ascending:false}).limit(60);if(!error)chatMessages.value=(data||[]).reverse()}
async function sendDivineMessage(){if(!client||!chatUser.value||!chatIsAdmin.value){chatError.value='Sign in to send a message.';return}const message=chatText.value.trim(),name=chatName.value.trim()||chatUser.value.email?.split('@')[0]||'Member';if(!message||message.length>1000)return;chatSending.value=true;chatError.value='';chatNotice.value='';const {error}=await client.from('george_divine_messages').insert({author_id:chatUser.value.id,author_name:name.slice(0,60),message});chatSending.value=false;if(error){chatError.value=error.message;return}chatText.value='';chatNotice.value='Message sent. George will consider it on his next simulation tick.';await refreshDivineChat()}
async function checkChatAdmin(){if(!client||!chatUser.value){chatIsAdmin.value=false;adminDaylight.value=false;return}const {data,error}=await client.from('george_chat_admins').select('user_id').eq('user_id',chatUser.value.id).maybeSingle();chatIsAdmin.value=!error&&!!data;if(error)console.warn('Admin status lookup failed:',error.message);if(!chatIsAdmin.value)adminDaylight.value=false}
async function submitAuth(){
 if(!client){authError.value='Sign-in is not configured.';return}
 const email=authEmail.value.trim().toLowerCase(),password=authPassword.value;
 authError.value='';authNotice.value='';
 if(authMode.value!=='update'&&!email.includes('@')){authError.value='Enter a valid email.';return}
 if(!['reset'].includes(authMode.value)&&password.length<6){authError.value='Use at least six characters.';return}
 authBusy.value=true;
 try{
  const redirect='https://theislandofgeorge.insytesolutionsnz.workers.dev/';
  let result;
  if(authMode.value==='register')result=await client.auth.signUp({email,password,options:{emailRedirectTo:redirect}});
  else if(authMode.value==='reset')result=await client.auth.resetPasswordForEmail(email,{redirectTo:redirect});
  else if(authMode.value==='update')result=await client.auth.updateUser({password});
  else result=await client.auth.signInWithPassword({email,password});
  if(result.error)throw result.error;
  if(authMode.value==='register'){authNotice.value=result.data?.session?'Account created and signed in.':'Check your email to confirm your account, then sign in.';if(result.data?.session){chatUser.value=result.data.user;await checkChatAdmin()}}
  else if(authMode.value==='reset')authNotice.value='Check your email for the password reset link.';
  else if(authMode.value==='update'){authNotice.value='Password updated.';authMode.value='signin';authOpen.value=false}
  else {chatUser.value=result.data.user;await checkChatAdmin();authOpen.value=false;tab.value='chat';chatNotice.value='Signed in successfully.'}
  authPassword.value='';
 }catch(e){authError.value=e.message||'Sign-in failed.'}finally{authBusy.value=false}
}
function openAuth(mode='signin'){authMode.value=mode;authOpen.value=true;authError.value='';authNotice.value=''}
async function signInForChat(){if(!client)return;chatError.value='';const email=chatEmail.value.trim();if(!email){chatError.value='Enter your email address.';return}const {error}=await client.auth.signInWithOtp({email,emailRedirectTo:'https://theislandofgeorge.insytesolutionsnz.workers.dev/'});if(error)chatError.value=error.message;else chatNotice.value='Check your email for a sign-in link.'}
async function signOutChat(){if(client)await client.auth.signOut();chatUser.value=null;chatIsAdmin.value=false;adminDaylight.value=false;authOpen.value=false}
onMounted(()=>{dispose=mountIsland(canvas.value,({phase:p,daylight:d,weather:w,temperature:t,thermal:th,swimming:s,wetness:wet,weatherSource:source,wind:windSpeed,freshwaterNearby,georgeMoving,resting,sitting})=>{phase.value=p;daylight.value=d;weather.value=w;temperature.value=t;thermal.value=th;swimming.value=s;wetness.value=wet;weatherSource.value=source;wind.value=windSpeed;activity.value={swimming:s,resting,sitting,freshwaterNearby,georgeMoving};if(!client)advanceSurvival({thermal:th,swimming:s,wetness:wet,freshwaterNearby,georgeMoving,resting})},{forceDaylight:()=>chatIsAdmin.value&&adminDaylight.value});loadData();client?.auth.getUser().then(({data})=>{chatUser.value=data?.user||null;checkChatAdmin()});client?.auth.onAuthStateChange((event,session)=>{chatUser.value=session?.user||null;checkChatAdmin();if(event==='PASSWORD_RECOVERY'){authMode.value='update';authOpen.value=true;authNotice.value='Choose a new password.'}});refreshDivineChat();refreshMemoryMap();refresh=setInterval(()=>{loadData();refreshDivineChat();if(tab.value==='memory')refreshMemoryMap()},15000)});
onUnmounted(()=>{dispose?.();clearInterval(refresh)});
</script>
<template>
<div class="shell">
<header class="topbar"><div class="brand"><div class="mark">G</div><div><span class="eyebrow">A LIVING ISLAND EXPERIMENT</span><h1>The Island of George</h1></div></div><div class="status"><label v-if="chatIsAdmin" class="admin-daylight-toggle" title="Visual preview only. Does not change island time or George’s behaviour."><input type="checkbox" v-model="adminDaylight"><span>Daytime view</span></label><button type="button" class="account-button" @click="openAuth(chatUser?'account':'signin')">{{chatUser?(chatIsAdmin?'Admin account':'My account'):'Sign in / Register'}}</button><span class="live-dot"></span> {{connected?'World data connected':'3D prototype'}} <span class="separator">·</span> Day {{world?.day||1}}</div></header>
<main class="layout">
<div class="world-column"><section class="scene-panel"><div class="scene" ref="canvas"></div><div class="scene-overlay"><label v-if="chatIsAdmin" class="admin-daylight-toggle scene-daylight-toggle" title="Only changes lighting on your screen"><input type="checkbox" v-model="adminDaylight"><span>☀ Daytime view</span></label><div class="pill">☀ {{timeLabel}} <span>·</span> {{Math.round(daylight*100)}}% daylight · {{clockLabel}} NZ</div><div class="scene-hint">Drag to orbit · Scroll to zoom · Unlock 🔓 for WASD movement</div></div><div class="scene-footer"><div><span class="eyebrow">GEORGE'S CURRENT WORLD</span><h2>Somewhere on a forgotten island</h2><p>Five biomes to explore. A lifetime of choices ahead.</p></div><span class="tag">PROTOTYPE</span></div></section>
<section class="panel survival-panel"><div class="section-title"><span class="eyebrow">SURVIVAL STATUS · LIVE PREVIEW</span><span class="tag">{{world?.status||'Preview'}}</span></div><h2>George's Health & Needs</h2><div class="meters"><div v-for="[name,value] in needs" :key="name" class="meter"><div class="meter-label"><span>{{name}}</span></div><div class="track dot-track"><span class="meter-dot" :style="{left:Math.max(0,Math.min(100,Number(value)))+'%'}"></span></div></div></div><div class="mood">✦ Mood: {{mood}} · Never sleeps, but needs rest</div><div class="meters" style="margin-top:16px"><div class="eyebrow" style="margin-bottom:10px">GEORGE'S EMOTIONAL STATE</div><div v-for="[name,value] in emotions" :key="name" class="meter"><div class="meter-label"><span>{{name}}</span></div><div class="track dot-track"><span class="meter-dot" :style="{left:Math.max(0,Math.min(100,Number(value)))+'%'}"></span></div></div></div><div v-if="connected" class="mood">🎒 Carrying {{carriedItems.length}} / 5 items: <span v-if="carriedItems.length">{{carriedItems.map(i=>itemLabel(i.type_id)).join(', ')}}</span><span v-else>Nothing</span> · {{storedItems.length}} stored at camp<span v-if="storedItems.length"> ({{storedItems.map(i=>itemLabel(i.type_id)).join(', ')}})</span></div><div v-if="project" class="mood">🏕 Shelter: {{project.shelter_built?'Built':'Not yet built'}} · Logs collected: {{project.logs_at_camp}} / 12 · Last activity: {{project.last_action.replaceAll('_',' ')}}</div><div class="mood">☁ {{weather}} · {{temperature}}°C · {{thermal}} · {{swimming?'Swimming':'On land'}} · Wet {{wetness}}%</div><div class="mood">Wind {{wind}} km/h · {{weatherSource}}</div><p class="muted survival-note">When connected, these are George's shared server-side survival values; otherwise browser preview values are shown.</p></section></div>
<aside class="sidebar"><section class="panel thought-panel"><div class="section-title"><span class="eyebrow">GEORGE'S CURRENT THOUGHTS</span><span class="tag">LIVE PREVIEW</span></div><h2>What George is thinking</h2><p class="thought-text">{{thought}}</p><p class="muted thought-disclaimer">When connected, this displays George's server-side decision; otherwise it shows a browser preview.</p></section><section class="panel journal"><div class="tabs"><button :class="{active:tab==='journal'}" @click="tab='journal'">Public journal</button><button :class="{active:tab==='about'}" @click="tab='about'">About the world</button><button :class="{active:tab==='chat'}" @click="tab='chat'">Chat with George</button><button :class="{active:tab==='memory'}" @click="tab='memory';refreshMemoryMap()">Memory Map</button></div><template v-if="tab==='journal'"><p v-if="!connected&&!loading" class="muted" style="padding:12px 18px 0;font-size:12px">Showing George’s first saved entry as a preview. Connect Supabase in Cloudflare to display new journal entries live.</p><div v-if="loading" class="empty">Checking George's journal…</div><div v-else-if="displayedJournal.length===0" class="empty"><div class="book">✎</div><h3>His story hasn't begun yet.</h3><p>When the autonomous AI engine starts writing, George's notes will appear here for everyone to read.</p></div><div class="journal-scroll" role="region" aria-label="George’s public journal entries" tabindex="0"><article v-for="item in displayedJournal" :key="item.id" class="entry"><div class="eyebrow">DAY {{item.island_day}} · {{item.perceived_time}}<span v-if="journalTimestamp(item.created_at)"> · {{journalTimestamp(item.created_at)}}</span></div><h3>{{item.title}}</h3><p>{{item.entry}}</p></article></div></template><div v-else-if="tab==='memory'" class="memory-panel"><p class="muted">Locations George has personally discovered. Faded markers indicate resources that may no longer be there.</p><label class="memory-filter">Show <select v-model="memoryFilter"><option value="all">All memories</option><option value="item">Resources and items</option><option value="camp">Camps</option><option value="clay">Clay</option></select></label><div class="memory-map" role="img" aria-label="Top-down map of George's discovered locations"><div class="memory-island"></div><div class="memory-centre">N ↑</div><span v-for="m in visibleMemories" :key="m.subject_type+'-'+m.subject_key" class="memory-pin" :class="[m.subject_type,{stale:!m.is_available}]" :style="{left:memoryPosition(m.x),top:memoryPosition(m.z)}" :title="m.subject_type+' · '+m.subject_key+' · seen '+m.visits+' times'">{{m.subject_type==='camp'?'⌂':m.subject_type==='clay'?'◆':'•'}}</span></div><p class="memory-count">{{visibleMemories.length}} discovered locations · Coordinates are approximate</p></div><div v-else-if="tab==='chat'" class="divine-chat"><p class="chat-intro">Messages from beyond the island are visible to everyone. Only the admin can send them; George can accept, consider or reject each message and give a short reply.</p><div class="chat-scroll" role="log" aria-label="Messages to George"><div v-for="msg in chatMessages" :key="msg.id" class="chat-entry"><div class="chat-meta"><strong>{{msg.author_name}}</strong> · {{journalTimestamp(msg.created_at)}}</div><p>{{msg.message}}</p><div v-if="msg.george_response" class="chat-reply"><strong>George · {{msg.status}}</strong><p>{{msg.george_response}}</p></div><div v-else class="chat-pending">Awaiting George’s response</div></div><p v-if="!chatMessages.length" class="muted">No messages yet. Be the first to speak to George.</p></div><div v-if="chatUser&&chatIsAdmin" class="chat-compose"><div class="chat-signed">Signed in as {{chatUser.email}} <button type="button" @click="signOutChat">Sign out</button></div><input v-model="chatName" maxlength="60" placeholder="Display name (optional)" aria-label="Display name"><textarea v-model="chatText" maxlength="1000" rows="3" placeholder="Speak to George…" aria-label="Message to George"></textarea><button type="button" :disabled="chatSending||!chatText.trim()" @click="sendDivineMessage">{{chatSending?'Sending…':'Send message to George'}}</button></div><div v-else-if="chatUser" class="chat-compose"><p>Only the administrator can send messages to George at present. You can still read the conversation.</p><button type="button" @click="signOutChat">Sign out</button></div><div v-else class="chat-compose"><p>Members can register and read George's chat. Only the administrator can post.</p><button type="button" @click="openAuth('signin')">Sign in to comment</button><button type="button" @click="openAuth('register')">Register as a member</button></div><p v-if="chatError" class="chat-error" role="alert">{{chatError}}</p><p v-if="chatNotice" class="chat-notice">{{chatNotice}}</p></div><div v-else class="about"><p>George will eventually make independent decisions, remember discoveries, react to visitors and document his life here.</p><p>Day and night in this preview follow New Zealand local time. The current 3D character follows a demo route rather than AI decisions.</p><p>All real simulation actions will be validated on the server.</p></div></section></aside>
</main><div v-if="authOpen" class="auth-backdrop" @click.self="authOpen=false"><section class="auth-dialog" role="dialog" aria-modal="true" aria-label="Account"><button class="auth-close" type="button" @click="authOpen=false" aria-label="Close">×</button><h2>{{authMode==='register'?'Create your account':authMode==='reset'?'Reset password':authMode==='update'?'Choose a new password':authMode==='account'?'Your account':'Sign in'}}</h2><template v-if="authMode==='account'"><p>Signed in as {{chatUser?.email}}</p><p>{{chatIsAdmin?'Administrator — can message George':'Member — read-only chat access'}}</p><button type="button" class="auth-primary" @click="tab='chat';authOpen=false">Open George's chat</button><button type="button" class="auth-secondary" @click="signOutChat">Sign out</button></template><form v-else @submit.prevent="submitAuth"><label v-if="authMode!=='update'">Email address<input v-model="authEmail" type="email" autocomplete="email" required></label><label v-if="authMode!=='reset'">{{authMode==='update'?'New password':'Password'}}<input v-model="authPassword" type="password" minlength="6" required :autocomplete="authMode==='signin'?'current-password':'new-password'"></label><button class="auth-primary" type="submit" :disabled="authBusy">{{authBusy?'Please wait…':authMode==='register'?'Create account':authMode==='reset'?'Send reset link':authMode==='update'?'Update password':'Sign in'}}</button><p v-if="authError" class="chat-error" role="alert">{{authError}}</p><p v-if="authNotice" class="chat-notice" role="status">{{authNotice}}</p><div class="auth-links"><button v-if="authMode!=='signin'" type="button" @click="authMode='signin';authError=''">Sign in</button><button v-if="authMode!=='register'&&authMode!=='update'" type="button" @click="authMode='register';authError=''">Register</button><button v-if="authMode==='signin'" type="button" @click="authMode='reset';authError=''">Forgot password?</button></div></form></section></div><footer>THE ISLAND OF GEORGE <span>·</span> A survival simulation in development <span>·</span> Forest assets by Dari (Sketchfab, CC BY) <span>·</span> {{connected?'Read-only Supabase connection active':'Live database not configured in deployment'}}</footer>
</div>
</template>